WITH valid AS (SELECT id, customer_id, account_type, balance, opened_date, status, CAST(balance AS INT) balance_int, TRIM(account_type) clean_account_type, COALESCE(status, 'OTHER') status_filled FROM accounts WHERE customer_id IS NULL AND opened_date >= DATE '2023-04-02') SELECT id, customer_id, balance, opened_date, AVG(balance_int) OVER (PARTITION BY customer_id ORDER BY balance, id ROWS BETWEEN 3 PRECEDING AND 1 PRECEDING) balance_int_avg_3_prior, LEAD(balance, 1) OVER (ORDER BY opened_date, id) next_balance, FIRST_VALUE(status) IGNORE NULLS OVER (PARTITION BY customer_id ORDER BY balance, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) first_known_status FROM valid WHERE balance >= 17000
